query:
query SchemaTypes {
  meta { name apiVersion { x y z } dataVersion { year month iteration } }
  Query: __type(name: "Query") { ...TypeInfo }
  Pagination: __type(name: "Pagination") { ...TypeInfo }
  Disease: __type(name: "Disease") { ...TypeInfo }
  DiseaseSynonyms: __type(name: "DiseaseSynonyms") { ...TypeInfo }
  AssociatedTargets: __type(name: "AssociatedTargets") { ...TypeInfo }
  AssociatedTarget: __type(name: "AssociatedTarget") { ...TypeInfo }
  ScoredComponent: __type(name: "ScoredComponent") { ...TypeInfo }
  Target: __type(name: "Target") { ...TypeInfo }
  clinicalTargets: __type(name: "clinicalTargets") { ...TypeInfo }
  ClinicalTargetFromTarget: __type(name: "ClinicalTargetFromTarget") { ...TypeInfo }
  clinicalIndicationsFromDiseaseImp: __type(name: "clinicalIndicationsFromDiseaseImp") { ...TypeInfo }
  ClinicalIndicationFromDisease: __type(name: "ClinicalIndicationFromDisease") { ...TypeInfo }
  clinicalIndicationsFromDrugImp: __type(name: "clinicalIndicationsFromDrugImp") { ...TypeInfo }
  ClinicalIndicationFromDrug: __type(name: "ClinicalIndicationFromDrug") { ...TypeInfo }
  ClinicalDiseaseListItem: __type(name: "ClinicalDiseaseListItem") { ...TypeInfo }
  ClinRepDrugListItem: __type(name: "ClinRepDrugListItem") { ...TypeInfo }
  ClinicalReport: __type(name: "ClinicalReport") { ...TypeInfo }
  ClinicalReportType: __type(name: "ClinicalReportType") { ...TypeInfo }
  Drug: __type(name: "Drug") { ...TypeInfo }
  MechanismsOfAction: __type(name: "MechanismsOfAction") { ...TypeInfo }
  MechanismOfActionRow: __type(name: "MechanismOfActionRow") { ...TypeInfo }
  Reference: __type(name: "Reference") { ...TypeInfo }
}

fragment TypeInfo on __Type {
  name
  kind
  description
  enumValues { name description }
  inputFields { name description defaultValue type { ...TypeRef } }
  fields {
    name
    description
    args { name defaultValue type { ...TypeRef } }
    type { ...TypeRef }
  }
}

fragment TypeRef on __Type {
  kind name
  ofType { kind name ofType { kind name ofType { kind name ofType { kind name } } } }
}
